import SwiftUI
struct JafarConnectionSettingsView: View { @Environment(\.dismiss) private var dismiss; @State private var endpoint = JafarClientConfiguration.endpointString; @State private var apiKey = ""; @State private var message: String?; var body: some View { Form { TextField("API endpoint", text: $endpoint); SecureField("API-ключ (Keychain)", text: $apiKey); Text("Ключ хранится только в Keychain и не отображается повторно.").font(.caption).foregroundStyle(.secondary); if let message { Text(message).font(.caption) }; HStack { Button("Отмена") { dismiss() }; Spacer(); Button("Сохранить") { save() }.buttonStyle(.borderedProminent) } }.padding().frame(minWidth: 420) }; private func save() { do { try JafarClientConfiguration.save(endpoint: endpoint, apiKey: apiKey.isEmpty ? nil : apiKey); message = "Подключение сохранено."; apiKey = "" } catch { message = error.localizedDescription } } }
